export const meta = {
  "slug": "animated-tooltip",
  "name": "Animated Tooltip",
  "family": "Overlays",
  "collection": "Surfaces",
  "component": "createLinearAnimatedTooltip"
};

export function createLinearAnimatedTooltip(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderLinearScene(svg, current);
  };
  render();
  const controller = bindLinearScene(root, current);
  return {
    replay: controller.replay,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
  };
}
